(()=>{'use strict';const root=document.querySelector('[data-adjustments-page]');if(!root)return;const list=root.querySelector('[data-list]'),summary=root.querySelector('[data-summary]');const money=(n,c)=>new Intl.NumberFormat(undefined,{style:'currency',currency:c||'USD'}).format((Number(n)||0)/100);async function load(){list.setAttribute('aria-busy','true');try{const r=await fetch('/api/admin/bundle-settlement-adjustments.php?action=queue',{credentials:'same-origin',headers:{Accept:'application/json'}});const j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.message||'Unable to load adjustments.');const items=j.items||j.data?.items||[];summary.textContent=`${items.length} adjustment${items.length===1?'':'s'}`;list.innerHTML=items.length?items.map(x=>`<article><div><span>${x.adjustment_type}</span><h2>${x.bundle_title||'Product Bundle'}</h2><p>${x.merchant_name||''} · ${x.order_public_id||''}</p><p>${x.reason||''}</p></div><div><strong>${money(x.amount_cents,x.currency)}</strong><span>${x.adjustment_status}</span>${['created','review_required','failed'].includes(x.adjustment_status)?`<button data-review="${x.public_id}" data-decision="approve">Approve</button><button data-review="${x.public_id}" data-decision="cancel">Cancel</button>`:''}</div></article>`).join(''):'<p class="empty">No settlement adjustments found.</p>';}catch(e){list.innerHTML=`<p class="error">${e.message}</p>`;}finally{list.setAttribute('aria-busy','false');}}async function review(id,decision){const fd=new FormData();fd.set('action','review');fd.set('adjustment_id',id);fd.set('decision',decision);fd.set('confirmation',decision==='approve'?'APPROVE':'');const token=document.querySelector('meta[name="csrf-token"]')?.content||document.querySelector('input[name="csrf_token"]')?.value||'';fd.set('csrf_token',token);const r=await fetch('/api/admin/bundle-settlement-adjustments.php',{method:'POST',body:fd,credentials:'same-origin',headers:{Accept:'application/json'}});const j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.message||'Unable to update adjustment.');await load();}root.addEventListener('click',e=>{const b=e.target.closest('[data-review]');if(b)review(b.dataset.review,b.dataset.decision).catch(err=>alert(err.message));if(e.target.closest('[data-refresh]'))load();});load();})();
